def check(n):
    if n <= 0:
        return False 
    temp = n
    so_chu_so = 0
    while temp > 0:
        so_chu_so += 1
        temp //= 10
    temp = n
    tong = 0
    while temp > 0:
        chu_so = temp % 10
        mu = 1
        for _ in range(so_chu_so):
            mu *= chu_so
        tong += mu
        temp //= 10
    if tong == n:
        return True
    else:
        return False
n = int(input())
print("true" if check(n) else "false")

